#!/usr/bin/env node
// One-off installer: registers the GitHub MCP server in this project's .mcp.json
// Usage: node install-github-mcp.mjs
//
// Requires a GitHub PAT (repo scope) in the GITHUB_PERSONAL_ACCESS_TOKEN env var
// at the time Claude Code actually launches the server (the token is referenced
// via ${GITHUB_PERSONAL_ACCESS_TOKEN}, never written into this file or the config).

import fs from "node:fs";
import path from "node:path";

const configPath = path.resolve(process.cwd(), ".mcp.json");

let config = { mcpServers: {} };
if (fs.existsSync(configPath)) {
  const raw = fs.readFileSync(configPath, "utf8");
  config = raw.trim() ? JSON.parse(raw) : { mcpServers: {} };
  config.mcpServers ??= {};
}

config.mcpServers.github = {
  type: "http",
  url: "https://api.githubcopilot.com/mcp/",
  headers: {
    Authorization: "Bearer ${GITHUB_PERSONAL_ACCESS_TOKEN}",
  },
};

fs.writeFileSync(configPath, JSON.stringify(config, null, 2) + "\n");
console.log(`Wrote GitHub MCP server entry to ${configPath}`);
